import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import Card from "../components/common/Card";
import * as SelectionData from "../constants/selection";
import Button from "../components/common/Button";
import { useUI } from "../context/UIContext";
import styles from "../Selections.module.css"; // 引入樣式

const Selections = () => {
  const navigate = useNavigate();
  const { setHeroData, allAnswers } = useUI();
  const [selectedId, setSelectedId] = useState(null);

  // 1. 同步 Hero 資訊
  useEffect(() => {
    setHeroData({
      imageUrl:
        "https://web-production-fbb7b.up.railway.app/static/helperinside.png",
      title: `${allAnswers.userName}您好，我可以幫您什麼呢？`,
      description: "請根據您想了解的問題選擇。",
    });
  }, [setHeroData]);

  // 2. 邏輯處理
  const handleConfirm = () => {
    if (!selectedId) {
      alert("請先選擇一個方案");
      return;
    }

    const paths = {
      1: "/SDM",
      2: "/chatbot",
    };

    const targetPath = paths[selectedId];
    if (targetPath) {
      navigate(targetPath);
    } else {
      console.warn("未定義的路徑");
    }
  };

  const currentSelection = SelectionData.selectionList.find(
    (s) => s.id === selectedId
  );

  return (
    <div className={`${styles.container} ${styles.fadeIn}`}>
      {/* 選擇列表區塊 */}
      {SelectionData.selectionList.map((item) => (
        <Card
          key={item.id}
          title={item.title}
          description={item.description}
          isActive={selectedId === item.id}
          onClick={() => setSelectedId(item.id)}
        />
      ))}

      {/* 按鈕群組區塊 */}
      <div className={styles.buttonGroup}>
        {/* 主要行為按鈕 */}
        <Button onClick={handleConfirm} fullWidth>
          {selectedId ? `開始使用 ${currentSelection?.title}` : "請選擇方案"}
        </Button>

        {/* 返回修改按鈕 */}
        <Button variant="outline" onClick={() => navigate("/")} fullWidth>
          返回重新填寫基本資料
        </Button>
      </div>
    </div>
  );
};

export default Selections;
